sys_script_include.script:
var RITMValidationAjax = Class.create();
RITMValidationAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    shouldShowBanner: function() {

        var ritmSysId = this.getParameter('sysparm_ritm_sys_id');

        var ritmGR = new GlideRecord('sc_req_item');
        if (!ritmGR.get(ritmSysId))
            return true;

        if (ritmGR.parent.nil())
            return false;

        var taskGR = new GlideRecord('sc_task');
        taskGR.addQuery('request_item', ritmSysId);
        taskGR.addQuery('short_description', 'CONTAINS', 'Failed to create story for RITM');
        taskGR.setLimit(1);
        taskGR.query();

        if (taskGR.hasNext())
            return true;

        return false;
    },

	validateClose: function () {

        var ritmSysId = this.getParameter('sysparm_ritm');

        var result = {
            valid: true,
            message: ''
        };

        // Check Catalog Tasks
        var taskGR = new GlideRecord('sc_task');
        taskGR.addQuery('request_item', ritmSysId);
        taskGR.addQuery('state', '!=', '3'); // Closed Complete
        taskGR.query();

        if (taskGR.hasNext()) {
            result.valid = false;
            result.message = 'All Catalog Tasks must be closed before closing the RITM.';
            return JSON.stringify(result);
        }

        // Check Parent Incident
        var ritmGR = new GlideRecord('sc_req_item');
        if (ritmGR.get(ritmSysId) && !ritmGR.parent.nil()) {

            var incGR = new GlideRecord('incident');
            if (incGR.get(ritmGR.parent) && incGR.state != '6') { // Resolved
                result.valid = false;
                result.message = 'Incident must be resolved before closing the RITM.';
            }
        }

        return JSON.stringify(result);
    },

    type: 'RITMValidationAjax'
});
